// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address _target, uint256 _value) internal {
        vm.assume(true);
        uint beforeTarget = _target.balance;
        bool reverted;
        try c.sendMoney(_target, _value) { reverted = false; } catch { reverted = true; }
        uint afterTarget = _target.balance;
        assertTrue(!reverted ? afterTarget == beforeTarget + _value : true);
    }

    function testFuzz_run(address _target, uint256 _value) public {
        _run(_target, _value);
    }

    receive() external payable {}
}
